<?php
require_once __DIR__.'/../lib/app.php';$pageTitle='대시보드';include '_top.php';$pdo=db();[$scopeSql,$scopeParams]=request_scope_sql('e');$q=trim($_GET['q']??'');$params=$scopeParams;$search='';if($q!==''){$search=' AND (e.name LIKE ? OR e.employee_no LIKE ? OR d.name LIKE ? OR lt.name LIKE ? OR lr.start_date LIKE ?)';for($i=0;$i<5;$i++)$params[]='%'.$q.'%';}
function scalarScoped($sql,$params){$s=db()->prepare($sql);$s->execute($params);return$s->fetchColumn();}
$stats=['직원'=>scalarScoped("SELECT COUNT(*) FROM employees e WHERE e.is_active=1 AND $scopeSql",$scopeParams),'승인대기'=>scalarScoped("SELECT COUNT(*) FROM leave_requests lr JOIN employees e ON e.id=lr.employee_id WHERE lr.status IN ('pending','in_approval') AND $scopeSql",$scopeParams),'오늘휴가'=>scalarScoped("SELECT COUNT(*) FROM leave_requests lr JOIN employees e ON e.id=lr.employee_id WHERE lr.status='approved' AND CURDATE() BETWEEN lr.start_date AND lr.end_date AND $scopeSql",$scopeParams),'내 결재대기'=>0];if(admin_employee_id()){$s=$pdo->prepare("SELECT COUNT(*) FROM request_approvals WHERE approver_employee_id=? AND status='pending'");$s->execute([admin_employee_id()]);$stats['내 결재대기']=$s->fetchColumn();}
$sql="SELECT lr.*,e.name,e.position,e.employee_no,d.name department_name,lt.name leave_name FROM leave_requests lr JOIN employees e ON e.id=lr.employee_id LEFT JOIN departments d ON d.id=e.department_id JOIN leave_types lt ON lt.id=lr.leave_type_id WHERE $scopeSql $search ORDER BY lr.id DESC LIMIT 100";$s=$pdo->prepare($sql);$s->execute($params);$recent=$s->fetchAll();
?><div class="page-title-row"><div><h1>대시보드</h1><p class="page-desc">권한 범위 내 직원·신청·결재 현황을 조회합니다.</p></div></div><form class="dashboard-search" method="get"><input name="q" value="<?=h($q)?>" placeholder="직원명, 사번, 부서, 휴가유형, 날짜 검색"><button class="btn">검색</button><?php if($q):?><a class="btn gray" href="dashboard.php">초기화</a><?php endif?></form><div class="grid"><?php foreach($stats as $k=>$v):?><div class="col3 card"><div class="muted"><?=h($k)?></div><div class="stats"><?=h($v)?></div></div><?php endforeach?></div><div class="card"><div class="section-head"><div><h2><?=$q?'검색 결과':'최근 신청'?></h2><p class="muted">직원명을 누르면 직원별 휴가현황으로 이동합니다.</p></div></div><div class="table-wrap"><table class="table"><tr><th>직원</th><th>부서</th><th>유형</th><th>기간</th><th>일수</th><th>상태</th></tr><?php if(!$recent):?><tr><td colspan="6" class="empty-cell">조회 결과가 없습니다.</td></tr><?php endif?><?php foreach($recent as $r):?><tr><td><a class="text-link" href="leave_status.php?employee_id=<?=$r['employee_id']?>"><?=h($r['name'].' '.$r['position'])?></a><div class="muted"><?=h($r['employee_no'])?></div></td><td><?=h($r['department_name']?:'-')?></td><td><?=h($r['leave_name'])?></td><td><?=h($r['start_date'])?> ~ <?=h($r['end_date'])?></td><td><?=fmt_days($r['requested_days'])?></td><td><span class="badge"><?=h($r['status'])?></span></td></tr><?php endforeach?></table></div></div><?php include '_bottom.php';?>